CREATE DATABASE IF NOT EXISTS researchhub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE researchhub;
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS papers (id BIGINT AUTO_INCREMENT PRIMARY KEY,canonical_id VARCHAR(255) NOT NULL UNIQUE,title TEXT NOT NULL,abstract LONGTEXT,doi VARCHAR(500),arxiv_ids JSON,pmids JSON,openalex_ids JSON,authors JSON,keywords JSON,journal VARCHAR(1000),publisher VARCHAR(500),publication_date DATE,publication_year INT,paper_type VARCHAR(150),citation_count BIGINT DEFAULT 0,sources JSON,paper_url TEXT,pdf_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_year(publication_year),FULLTEXT KEY ft_paper(title,abstract)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS paper_sources (id BIGINT AUTO_INCREMENT PRIMARY KEY,paper_id BIGINT NOT NULL,source VARCHAR(50) NOT NULL,source_record_id VARCHAR(255),doi VARCHAR(500),source_url TEXT,source_metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(paper_id) REFERENCES papers(id) ON DELETE CASCADE,UNIQUE KEY uq_source_record(source,source_record_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS saved_papers (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,paper_id BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_user_paper(user_id,paper_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(paper_id) REFERENCES papers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_history (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,role ENUM('user','assistant') NOT NULL,message LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_chat_user(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS paper_analyses (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,filename VARCHAR(255),paper_title TEXT,analysis_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_analysis_user(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,category VARCHAR(100) NOT NULL,subject VARCHAR(180) NOT NULL,message TEXT NOT NULL,status ENUM('Open','In Progress','Resolved') NOT NULL DEFAULT 'Open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_ticket_created(created_at),INDEX idx_ticket_user(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
